//! Corresponding source archive embedded at build time.
//!
//! The archive is generated by `boot-api/build.rs` from the exact source used
//! to build this binary. It is served by `GET /v1/source` and offered to every
//! network user under AGPLv3 section 13.

/// SPDX identifier reported by the server status.
pub const LICENSE: &str = "AGPL-3.0-or-later";

/// Public path of the source download.
pub const URL: &str = "/v1/source";

/// The exact source archive embedded in this binary.
pub const ARCHIVE: &[u8] = include_bytes!(concat!(env!("OUT_DIR"), "/source.tar"));

/// Hex-encoded SHA-256 of `ARCHIVE`.
pub const SHA256: &str = env!("BOOT_SOURCE_SHA256");

/// Download filename presented to clients.
pub const FILENAME: &str = env!("BOOT_SOURCE_FILENAME");

/// Git commit used to build this binary, or `unknown`.
pub const REVISION: &str = env!("BOOT_SOURCE_REVISION");

/// Whether the source tree had uncommitted changes when this binary was built.
pub fn dirty() -> bool {
    env!("BOOT_SOURCE_DIRTY") == "true"
}

/// Public path of the dependency source redirect.
pub const DEPENDENCY_URL: &str = "/v1/source/dependencies";

/// Public path of the dependency source manifest.
pub const DEPENDENCY_MANIFEST_URL: &str = "/v1/source/manifest";

/// Immutable release URL for the dependency source bundle, or empty.
pub const DEPENDENCY_SOURCE_URL: &str = env!("BOOT_DEPENDENCY_SOURCE_URL");

/// SHA-256 of the dependency source bundle, or empty.
pub const DEPENDENCY_SOURCE_SHA256: &str = env!("BOOT_DEPENDENCY_SOURCE_SHA256");

/// Download filename of the dependency source bundle.
pub const DEPENDENCY_SOURCE_FILENAME: &str = env!("BOOT_DEPENDENCY_SOURCE_FILENAME");

/// Comma-separated build targets covered by the dependency bundle.
pub const DEPENDENCY_SOURCE_TARGETS: &str = env!("BOOT_DEPENDENCY_SOURCE_TARGETS");

/// Number of vendored packages in the dependency bundle.
pub const DEPENDENCY_SOURCE_PACKAGE_COUNT: &str = env!("BOOT_DEPENDENCY_SOURCE_PACKAGES");

/// Whether this build has a dependency source bundle.
pub fn dependency_source_available() -> bool {
    !DEPENDENCY_SOURCE_URL.is_empty()
}

/// Parsed target list for the dependency source bundle.
pub fn dependency_source_targets() -> Vec<String> {
    DEPENDENCY_SOURCE_TARGETS
        .split(',')
        .map(str::trim)
        .filter(|target| !target.is_empty())
        .map(|target| target.to_string())
        .collect()
}

/// Number of packages in the dependency source bundle.
pub fn dependency_source_packages() -> usize {
    DEPENDENCY_SOURCE_PACKAGE_COUNT.parse().unwrap_or_default()
}

/// Wire description of the dependency source offer.
pub fn dependency_source() -> boot_protocol::DependencySource {
    boot_protocol::DependencySource {
        license: LICENSE.to_string(),
        available: dependency_source_available(),
        url: DEPENDENCY_SOURCE_URL.to_string(),
        sha256: DEPENDENCY_SOURCE_SHA256.to_string(),
        filename: DEPENDENCY_SOURCE_FILENAME.to_string(),
        targets: dependency_source_targets(),
        packages: dependency_source_packages(),
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use sha2::{Digest, Sha256};
    use std::fmt::Write as _;

    #[test]
    fn archive_hash_matches_metadata() {
        let mut digest = String::new();
        for byte in Sha256::digest(ARCHIVE) {
            write!(digest, "{byte:02x}").unwrap();
        }
        assert_eq!(digest, SHA256);
    }

    #[test]
    fn archive_is_a_tar_with_source_files() {
        assert!(ARCHIVE.windows(7).any(|window| window == b"LICENSE"));
        assert!(ARCHIVE.windows(6).any(|window| window == b"NOTICE"));
        assert!(ARCHIVE.windows(10).any(|window| window == b"Cargo.lock"));
    }
}
